"use strict";function*counter(o){try{for(let n=0;n<o;n++){const e=yield n;e&&console.log("got",e)}return"done"}finally{console.log("cleanup")}}const it=counter(3);console.log(JSON.stringify(it.next()),JSON.stringify(it.next("a"))),console.log(JSON.stringify(it.return("early")),JSON.stringify(it.next())),console.log([...counter(2)].join(","));function*deleg(){yield"r="+(yield*counter(1))}console.log([...deleg()].join(","));function*thrower(){try{yield 1}catch(o){yield"caught "+o}yield 3}const t=thrower();t.next(),console.log(t.throw("x").value,t.next().value,t.next().done);function*labelled(){o:for(const o of[1,2])for(const n of[1,2]){if(n===2)continue o;yield o*10+n}}console.log([...labelled()].join(","));const gen={*[Symbol.iterator](){yield"x",yield"y"}};console.log([...gen].join("")),console.log(typeof counter,counter.name);try{const o=counter(1);o.next(),o.throw(new TypeError("t"))}catch(o){console.log(o.constructor.name)}function*fib(){let[o,n]=[0,1];for(;;)yield o,[o,n]=[n,o+n]}const firsts=[];for(const o of fib()){if(o>20)break;firsts.push(o)}console.log(firsts.join(","));
